// ⚙️ CONFIG — the only node you need to edit.
const config = {
  // Your Jira Cloud site. Must match the Jira credential.
  jiraBaseUrl: 'https://your-company.atlassian.net',

  // Bugs that passed "AI Bug Intake" and still need triage. One ticket per run keeps runs readable.
  jql: 'project = BUG AND issuetype = Bug AND status = "Triage" AND labels = ai-repro-checked AND labels not in (ai-triaged, ai-needs-human) ORDER BY created ASC',

  // Who gets tagged when a ticket is closed: 'reporter' or a user-picker custom field id.
  requesterField: 'reporter',

  // Below this confidence (0-100) the AI does not act on its own decision: it tags the ticket for a human.
  confidenceThreshold: 70,

  // Status NAMES as shown on your board.
  statuses: {
    waitingForInfo: 'Waiting for info', // open questions in the comments
    notABug: 'Closed',                  // not a bug (with a polite explanation to the reporter)
    escalated: 'Ready for Dev',         // confirmed bug, fields filled, handed to developers
  },

  labels: {
    triaged: 'ai-triaged',
    needsHuman: 'ai-needs-human',
  },

  models: {
    fast: 'gpt-5.4-mini', // classification and one-line fields
    smart: 'gpt-5.5',     // steps to reproduce
  },

  // Fields the AI extracts from the ticket. Every value goes into one triage comment.
  // target: where to also WRITE the value:
  //   ''                   → comment only
  //   'summary'            → the issue summary
  //   'priority'           → the priority field (values must match your priority names)
  //   'components'         → the Components field (values must match component names)
  //   'customfield_XXXXX'  → a custom field (fieldType 'option' for select lists, 'text' otherwise).
  //                          Find the number in Jira: Settings → Issues → Custom fields → ⋯ → Edit; it's in the URL (id=10050).
  // allowed: the model must return one of these values, or the field is skipped.
  // fallback: value to use when the ticket doesn't say (null = leave empty).
  // Remove a field, or set enabled: false, to stop extracting it.
  fields: [
    {
      key: 'summary', label: 'Summary', target: 'summary', model: 'fast',
      rules: 'Rewrite the summary in this format: [Environment] - [Area] - [Defect + trigger]. Environment is a short key such as Prod, Staging, QA or Dev ("Unknown Env" if not stated). Area is the affected feature, page, API or module in 2-6 words. Defect + trigger states the broken behaviour and when it happens ("when ...", "after ...", "on ..."). Present tense, under 140 characters. No ticket ids, names, dates, severity or priority. Avoid vague words such as issue, problem, bug or does not work.',
    },
    {
      key: 'stepsToReproduce', label: 'Steps to reproduce', target: '', model: 'smart', multiline: true,
      rules: 'Numbered steps, one per line ("1. ..."). One imperative action per step. Only the actions needed to reproduce the bug. No expected or actual result, environment or notes. If steps are not written but the user actions are clearly described, turn those actions into steps.',
    },
    {
      key: 'expectedResult', label: 'Expected result', target: '', model: 'fast',
      rules: 'What should happen when the steps are performed. One specific sentence in present tense. If it is not stated but is directly implied by the defect, write the intended correct behaviour.',
    },
    {
      key: 'actualResult', label: 'Actual result', target: '', model: 'fast',
      rules: 'What actually happens. One specific sentence in present tense.',
    },
    {
      key: 'environment', label: 'Environment', target: '', fieldType: 'option', model: 'fast',
      rules: 'Only if the ticket states it. If several are mentioned, pick the one where the bug was found or reproduced.',
      allowed: [
        { value: 'Production', meaning: 'production, prod, live, real customers' },
        { value: 'Staging', meaning: 'staging, pre-production, QA or test environment, sandbox' },
      ],
    },
    {
      key: 'setup', label: 'Setup', target: '', model: 'fast',
      rules: 'Format: OS | Browser | Device, where Device is Desktop or Mobile. Include only the parts the ticket states; drop unknown parts and their separators.',
    },
    {
      key: 'affectedUser', label: 'Affected user', target: '', model: 'fast',
      rules: 'Identifiers of the affected user or account (user id, email, username, account or customer id) exactly as written. Not the reporter or staff unless they are the affected user. Separate several with " | ".',
    },
    {
      key: 'url', label: 'URL', target: '', model: 'fast',
      rules: 'The URL of the page or screen where the bug happens, exactly as written. Not attachments, logs, documentation or Jira links. Separate several with " | ".',
    },
    {
      key: 'reproductionRate', label: 'Reproduction rate', target: '', model: 'fast',
      rules: 'The reproduction rate exactly as stated (for example "3/5" or "every time"). Do not estimate it from vague wording such as sometimes.',
    },
    {
      key: 'severity', label: 'Severity', target: '', fieldType: 'option', model: 'fast', fallback: 'Medium',
      rules: 'Judge by real user and business impact, affected flow, scope and workaround. Do not pick a higher value just because the ticket sounds urgent.',
      allowed: [
        { value: 'Critical', meaning: 'showstopper in production: a core flow is completely blocked or money is being lost, and there is no workaround' },
        { value: 'High', meaning: 'large impact on a main flow: many users blocked or high support volume; any workaround is hard or manual' },
        { value: 'Medium', meaning: 'noticeable impact on a main or side flow, but a practical workaround exists' },
        { value: 'Low', meaning: 'minor inconvenience: cosmetic, wording or layout issues, or rarely used flows' },
      ],
    },
    {
      key: 'priority', label: 'Priority', target: 'priority', model: 'fast', fallback: 'Medium',
      rules: 'Priority is fixing order: how soon this should be fixed, based on urgency, business value, scope and workaround. Use severity as context, do not copy it blindly.',
      allowed: [
        { value: 'Highest', meaning: 'fix now: blocks a critical production flow or causes major business loss, no practical workaround' },
        { value: 'High', meaning: 'fix as soon as possible: important flow, many users or a key customer, or only a hard workaround' },
        { value: 'Medium', meaning: 'important but can wait: limited scope or a clear workaround' },
        { value: 'Low', meaning: 'nice to have: cosmetic, minor or rarely used' },
      ],
    },
    {
      key: 'team', label: 'Owning team', target: '', fieldType: 'option', model: 'fast',
      rules: 'Pick the team that owns the system where the defect occurs, not where it was reported. Replace these example teams with your own.',
      allowed: [
        { value: 'Web', meaning: 'the customer-facing website and its pages, forms and flows' },
        { value: 'Mobile', meaning: 'the iOS or Android app, push notifications, mobile-only behaviour' },
        { value: 'Backend', meaning: 'APIs, integrations, data sync, database, infrastructure, internal tools' },
      ],
    },
  ],
};

// Manual test on one ticket: set a key here, then press "Test workflow". Ignored on scheduled runs.
const testIssueKey = '';
config.searchJql = $('▶ Test run').isExecuted && testIssueKey ? `key = ${testIssueKey}` : config.jql;
return [{ json: config }];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}

function personFrom(value) {
  // Works for the reporter field and for single or multi user-picker custom fields.
  const p = Array.isArray(value) ? value[0] : value;
  return { accountId: p?.accountId || '', name: p?.displayName || '' };
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const issue = ($input.first().json.issues || [])[0];
if (!issue) return []; // nothing to triage this run
const f = issue.fields || {};
const requester = personFrom(f[cfg.requesterField] ?? f.reporter);
return [{
  json: {
    key: issue.key,
    summary: f.summary || '',
    description: adfToText(f.description).trim(),
    requesterAccountId: requester.accountId,
    requesterName: requester.name,
  },
}];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}
// ---- end helpers ----

const ticket = $('Prepare ticket').first().json;
const comments = ($input.first().json.comments || [])
  .map((c) => {
    const text = adfToText(c.body).replace(/\s+/g, ' ').trim();
    return text ? `[${c.created || ''}] ${c.author?.displayName || 'Unknown'}: ${text}` : null;
  })
  .filter(Boolean)
  .join('\n\n');
return [{ json: { ...ticket, comments: comments || '(no comments)' } }];

// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}

function parseLlmJson(text) {
  // Returns the parsed object, or null if the model did not return valid JSON.
  const cleaned = String(text ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { /* try the first {...} block */ }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch (e) { return null; }
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const ticket = $('Add comments to context').first().json;
const ai = parseLlmJson(getLlmText($input.first().json));
const confidence = Number(ai?.confidence);
let route = 'human';
let reason = 'The model did not return a usable answer about open questions.';
if (ai && typeof ai.unansweredQuestions === 'boolean' && Number.isFinite(confidence)) {
  reason = String(ai.reason || '');
  if (confidence < cfg.confidenceThreshold) route = 'human';
  else route = ai.unansweredQuestions ? 'waiting' : 'continue';
}
return [{ json: { ...ticket, route, check: 'open questions', confidence: Number.isFinite(confidence) ? confidence : null, reason } }];

// Finds the transition that leads to the configured status NAME.
const key = $('Prepare ticket').first().json.key;
const target = String($('⚙️ Config').first().json.statuses.waitingForInfo).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };

// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
