  // Returns the parsed object, or null if the model did not return valid JSON.
  const cleaned = String(text ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { /* try the first {...} block */ }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch (e) { return null; }
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const ticket = $('Add comments to context').first().json;
const ai = parseLlmJson(getLlmText($input.first().json));
const confidence = Number(ai?.confidence);
const closure = String(ai?.closure_message || '').trim();
let route = 'human';
let reason = 'The model did not return a usable bug / not-a-bug answer.';
if (ai && typeof ai.is_bug === 'boolean' && Number.isFinite(confidence)) {
  reason = String(ai.reason || '');
  if (confidence < cfg.confidenceThreshold) route = 'human';
  else if (ai.is_bug) route = 'bug';
  else route = closure ? 'notBug' : 'human';
}
return [{ json: { ...ticket, route, check: 'bug or not', confidence: Number.isFinite(confidence) ? confidence : null, reason, closureMessage: closure } }];

// Finds the transition that leads to the configured status NAME.
const key = $('Read bug check').first().json.key;
const target = String($('⚙️ Config').first().json.statuses.notABug).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };

// Turns the field list in ⚙️ Config into one LLM call per field (focused prompts are easier to tune).
const cfg = $('⚙️ Config').first().json;
const t = $input.first().json;
const fields = (cfg.fields || []).filter((f) => f.enabled !== false);
if (!fields.length) throw new Error('No fields enabled in ⚙️ Config → fields.');
return fields.map((f) => {
  const allowed = Array.isArray(f.allowed) ? f.allowed : [];
  const allowedText = allowed.length
    ? 'Return exactly one of these values:\n' + allowed.map((a) => `- ${a.value}: ${a.meaning || ''}`).join('\n')
    : '';
  return {
    json: {
      key: t.key, summary: t.summary, description: t.description, comments: t.comments,
      field: f.key, label: f.label || f.key, rules: f.rules || '', allowedText,
      multiline: Boolean(f.multiline),
      model: cfg.models[f.model || 'fast'] || cfg.models.fast,
    },
  };
});

