// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}
// ---- end helpers ----

// Every model answer is checked before it can touch Jira:
// single-line where required, allowed values only, UNKNOWN → fallback or skipped.
const cfg = $('⚙️ Config').first().json;
const ticket = $('Read bug check').first().json;
const jobs = $('One job per field').all().map((i) => i.json);
const answers = $input.all();
const byKey = Object.fromEntries((cfg.fields || []).map((f) => [f.key, f]));

const fields = {};
const lines = [];
const skipped = [];

answers.forEach((answer, i) => {
  const job = jobs[i];
  const def = byKey[job.field] || {};
  let value = '';
  try { value = String(getLlmText(answer.json)); } catch (e) { skipped.push(`${job.label}: no answer`); return; }
  value = value.trim().replace(/^["'`]+|["'`]+$/g, '').trim();
  if (!job.multiline) value = value.replace(/\s*\n+\s*/g, ' ');
  let note = '';
  if (!value || /^(unknown|n\/?a|none)$/i.test(value)) {
    value = def.fallback || '';
    if (value) note = ' _(default — not stated in the ticket)_';
  }

  if (value && Array.isArray(def.allowed) && def.allowed.length) {
    const hit = def.allowed.find((a) => a.value.toLowerCase() === value.toLowerCase());
    if (hit) value = hit.value;
    else {
      const answered = value.slice(0, 60);
      value = def.fallback || '';
      if (!value) { skipped.push(`${job.label}: "${answered}" is not an allowed value`); return; }
      note = ` _(default — the model answered "${answered}", which is not an allowed value)_`;
    }
  }
  if (!value) { skipped.push(`${job.label}: not stated in the ticket`); return; }

  lines.push(job.multiline ? `*${job.label}:*\n${value}` : `*${job.label}:* ${value}${note}`);

  const target = def.target || '';
  if (!target) return;
  if (target === 'summary') fields.summary = value.slice(0, 254);
  else if (target === 'priority') fields.priority = { name: value };
  else if (target === 'components') fields.components = [{ name: value }];
  else if (def.fieldType === 'option') fields[target] = { value };
  else fields[target] = value;
});

const comment = [
  `*Automated triage* — confirmed as a bug (confidence ${ticket.confidence}%). ${ticket.reason}`,
  '',
  ...lines,
  ...(skipped.length ? ['', '_Not filled:_ ' + skipped.join('; ')] : []),
].join('\n');

return [{
  json: {
    key: ticket.key,
    hasFieldUpdates: Object.keys(fields).length > 0,
    updateBody: { fields },
    comment,
    written: Object.keys(fields),
    skipped,
  },
}];

// Finds the transition that leads to the configured status NAME.
const key = $('Validate fields').first().json.key;
const target = String($('⚙️ Config').first().json.statuses.escalated).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };
